  rainbowButton.style('border', '1px solid rgba(255,255,255,0.3)');
  rainbowButton.style('border-radius', '5px');
  rainbowButton.style('padding', '8px 16px');
  rainbowButton.style('cursor', 'pointer');
  rainbowButton.style('font-family', 'Arial, sans-serif');
  rainbowButton.style('font-size', '14px');
  rainbowButton.style('transition', 'all 0.3s');
  rainbowButton.parent(sliderContainer);
  rainbowButton.mousePressed(toggleRainbow);

  // Temperature display
  let tempDisplay = createElement('span', '50%');
  tempDisplay.style('color', 'white');
  tempDisplay.style('font-size', '14px');
  tempDisplay.style('font-family', 'Arial, sans-serif');
  tempDisplay.style('min-width', '40px');
  tempDisplay.style('text-align', 'center');
  tempDisplay.parent(sliderContainer);

  // Update display when slider changes
  temperatureSlider.input(() => {
    colorTemperature = temperatureSlider.value();
    tempDisplay.html(Math.round(colorTemperature * 100) + '%');
    // Update existing particles colors
    for (let p of particles) {
      if (!p.exploding) {
        p.colorTemperature = colorTemperature;
        p.color = p.getTemperatureColor(colorTemperature);
      }
    }
  });
}

function toggleRainbow() {
  rainbowMode = !rainbowMode;
  if (rainbowMode) {
    rainbowButton.style('background', 'rgba(255,0,255,0.3)');
    rainbowButton.style('border-color', '#ff00ff');
    rainbowButton.html('🌈 Rainbow ON');
  } else {
    rainbowButton.style('background', 'rgba(255,255,255,0.1)');
    rainbowButton.style('border-color', 'rgba(255,255,255,0.3)');
    rainbowButton.html('🌈 Rainbow');
  }
}

function drawBackground() {
  // Dark gradient background
  for (let y = 0; y < height; y += 2) {
    let inter = y / height;
    var r = lerp(5, 10, inter);
    var g = lerp(0, 5, inter);
    var b = lerp(15, 30, inter);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Add subtle grid
  stroke(255, 15);
  strokeWeight(0.5);
  let gridSize = 50;
  for (let x = 0; x < width; x += gridSize) {
    line(x, 0, x, height);
  }
  for (let y = 0; y < height; y += gridSize) {
    line(0, y, width, y);
  }
}

function draw() {
  // Fade background for trail effect
  noStroke();
  fill(0, 0, 0, 20);
  rect(0, 0, width, height);

  // Draw and update ink stains
  for (let i = explosionStains.length - 1; i >= 0; i--) {
    var stain = explosionStains[i];
    if (!stain.update()) {
      explosionStains.splice(i, 1);
    } else {
      stain.draw();
    }
  }

  // Update rainbow mode
  if (rainbowMode) {
    rainbowHue = (rainbowHue + 0.002) % 1;
    // Update particles with rainbow colors
    for (let p of particles) {
      if (!p.exploding) {
        let hue = (rainbowHue + p.id * 0.01) % 1;
        p.color = hslToHex(hue, 1, 0.6);
      }
    }
  }

  // Update and draw particles
  for (let i = particles.length - 1; i >= 0; i--) {
    var p = particles[i];
    p.update(mouseTarget.x, mouseTarget.y);
    p.draw();

    // Remove dead particles
    if (!p.alive) {
      particles.splice(i, 1);
      continue;
    }

    // Check collisions
    for (let j = i - 1; j >= 0; j--) {
      let other = particles[j];
      if (!other.alive || other.exploding) continue;
      if (p.checkCollision(other)) {
        // Remove the merged particle
        if (!other.alive) {
          particles.splice(j, 1);
        }
        break;
      }
    }
  }

  // Update mouse target
  mouseTarget.x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
  mouseTarget.y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));

  // Draw UI info
  drawUI();
}

function drawUI() {
  fill(255, 150);
  noStroke();
  textAlign(LEFT, TOP);
  textSize(12);
  text(`Particles: ${particles.length} | Stains: ${explosionStains.length}`, 10, 10);

  textSize(10);
  fill(255, 80);
  text('Click: summon | Drag: stream | Space: explode all | R: reset | F: fullscreen', 10, 30);
}

function mousePressed() {
  // Create particles at mouse position with current temperature
  for (let i = 0; i < particlesPerClick; i++) {
    var x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) + random(-10, 10);
    var y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) + random(-10, 10);
    var p = new Particle(x, y, colorTemperature);
    particles.push(p);
  }

  // Add a small shockwave effect with inertia
  for (let p of particles) {
    var dx = p.x - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
    var dy = p.y - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
    var dist = sqrt(dx*dx + dy*dy);
    if (dist < 100 && dist > 0) {
      let force = (1 - dist/100) * 3;
      p.vx += dx / dist * force * 0.5;
      p.vy += dy / dist * force * 0.5;
    }
  }
}

function mouseDragged() {
  // Continuously spawn particles while dragging
  if (frameCount % 3 === 0) {
    var p = new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) + random(-5, 5), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) + random(-5, 5), colorTemperature);
    particles.push(p);
  }
}

function keyPressed() {
  if (key === ' ') {
    // Trigger all particles to explode
    for (let p of particles) {
      if (!p.exploding) {
        p.startExplosion();
      }
    }
  }

  if (key === 'r' || key === 'R') {
    // Reset scene
    particles = [];
    explosionStains = [];
    drawBackground();
  }

  if (key === 'f' || key === 'F') {
    // Toggle fullscreen
    let fs = fullscreen();
    fullscreen(!fs);
    if (!fs) {
      resizeCanvas(windowWidth, windowHeight);
    }
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  drawBackground();
}

